SELECT s.*, c.class_name, cat.category_name, t.name AS teacher_name, r.classroom_name


     AND s.course_date BETWEEN #{startDate} AND #{endDate}
     AND s.teacher_id=#{teacherId}
     AND s.classroom_id=#{classroomId}
     AND s.class_id=#{classId}

ORDER BY s.course_date, s.start_time

SELECT COUNT(*) FROM course_schedule
WHERE teacher_id=#{teacherId} AND course_date=#{courseDate} AND status <> '已取消'
AND start_time < #{endTime} AND end_time > #{startTime}
 AND schedule_id <> #{excludeId}

SELECT COUNT(*) FROM course_schedule
WHERE classroom_id=#{classroomId} AND course_date=#{courseDate} AND status <> '已取消'
AND start_time < #{endTime} AND end_time > #{startTime}
 AND schedule_id <> #{excludeId}

SELECT COUNT(*) FROM course_schedule
WHERE class_id=#{classId} AND course_date=#{courseDate} AND status <> '已取消'
AND start_time < #{endTime} AND end_time > #{startTime}
 AND schedule_id <> #{excludeId}

SELECT * FROM course_schedule
WHERE course_date=#{courseDate} AND status <> '已取消'
AND start_time < #{endTime} AND end_time > #{startTime}
 AND schedule_id <> #{excludeId}
ORDER BY start_time
